steps.script:
# Same position as exam mv08 (without the profile line): Custodian Guard
# Alpha locked with the enemy Prosecutors west of no man's land, our
# Prosecutors locked with the enemy Allarus Custodians in the north strip,
# Custodian Guard Gamma holding obj_home_1, everyone else parked.
var st = GameState.state
var lines = {
	"U_CUSTODIAN_GUARD_A": [60.0, 65.0, 840.0],
	"U_PROSECUTORS_A_P2": [90.0, 50.0, 920.0],
	"U_ALLARUS_CUSTODIANS_A_P2": [1150.0, 65.0, 100.0],
	"U_PROSECUTORS_A": [1180.0, 50.0, 180.0],
}
for uid in lines:
	var spec = lines[uid]
	var k = 0
	for m in st.units[uid].models:
		m.position = {"x": spec[0] + spec[1] * float(k), "y": spec[2]}
		k += 1
var gpos = [Vector2(640, 420), Vector2(705, 420), Vector2(770, 420), Vector2(672, 485), Vector2(737, 485)]
var j = 0
for m in st.units.U_CUSTODIAN_GUARD_C.models:
	m.position = {"x": gpos[j].x, "y": gpos[j].y}
	j += 1
var p1 = 0
var p2 = 0
for uid in st.units:
	if uid in ["U_CUSTODIAN_GUARD_A", "U_PROSECUTORS_A_P2", "U_ALLARUS_CUSTODIANS_A_P2", "U_PROSECUTORS_A", "U_CUSTODIAN_GUARD_C"]:
		continue
	var u = st.units[uid]
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 50.0 + 70.0 * float(p1 % 6), "y": 50.0 + 70.0 * float(p1 / 6)}
			p1 += 1
		else:
			m.position = {"x": 1300.0 + 70.0 * float(p2 % 6), "y": 2320.0 - 70.0 * float(p2 / 6)}
			p2 += 1
return RulesEngine.is_unit_engaged("U_CUSTODIAN_GUARD_A", GameState.state) and RulesEngine.is_unit_engaged("U_PROSECUTORS_A", GameState.state)

# FIX_STAY_ENGAGED ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/stay_engaged_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

# Engine-level check of the same suggestion: Custodian Guard Alpha, a
# REMAIN_STATIONARY that says it stays engaged, with the engaged_choice
# record that picked "stay".
var d = AIPlayer.request_suggestion("")
var ok_rec = false
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) == "engaged_choice":
		var c = r.get("candidates", [])
		var ci = int(r.get("chosen_index", -1))
		ok_rec = ci >= 0 and ci < c.size() and str(c[ci].get("key", "")) == "stay"
return str(d.get("type", "")) == "REMAIN_STATIONARY" and str(d.get("actor_unit_id", "")) == "U_CUSTODIAN_GUARD_A" and str(d.get("_ai_description", "")).begins_with("Custodian Guard Alpha stays engaged with Prosecutors") and ok_rec

# SHIPPED-DEFAULT CHECK: clearing the profile leaves FIX_STAY_ENGAGED at 0 —
# the old fall back, the old description, no engaged_choice record, no notes.
AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("")
var has_rec = false
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) == "engaged_choice":
		has_rec = true
return str(d.get("type", "")) == "BEGIN_FALL_BACK" and str(d.get("_ai_description", "")) == "Custodian Guard Alpha falls back (not on objective)" and not d.has("_ai_move_adjustments") and not has_rec

# ...and reloading the profile restores the stay.
var f = FileAccess.open("res://tests/bench_profiles/stay_engaged_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("")
return str(d.get("type", "")) == "REMAIN_STATIONARY" and str(d.get("_ai_description", "")).contains("stays engaged")

# Execute the stay as the AI would (AIPlayer routes the decision as-is), then
# ask the ENGINE: moved (remained stationary), did not fall back, every model
# where it stood, still engaged with the Prosecutors.
var d = AIPlayer.request_suggestion("")
var r = NetworkIntegration.route_action({"type": "REMAIN_STATIONARY", "actor_unit_id": "U_CUSTODIAN_GUARD_A", "player": 1, "_ai_description": str(d.get("_ai_description", ""))})
var u = GameState.state.units.U_CUSTODIAN_GUARD_A
var k = 0
var still = true
for m in u.models:
	var p = m.get("position")
	var pv = p if p is Vector2 else Vector2(float(p.x), float(p.y))
	if pv.distance_to(Vector2(60.0 + 65.0 * float(k), 840.0)) > 1.0:
		still = false
	k += 1
return r != null and bool(r.get("success", false)) and bool(u.get("flags", {}).get("moved", false)) and not bool(u.get("flags", {}).get("fell_back", false)) and still and RulesEngine.is_unit_engaged("U_CUSTODIAN_GUARD_A", GameState.state)

# The guard pair, live: our Prosecutors' suggested fall back staged and
# confirmed through AIPlayer's own execution path, then checked on the engine
# (fell back, unengaged — 09.07).
var d = AIPlayer.request_suggestion("")
if str(d.get("actor_unit_id", "")) != "U_PROSECUTORS_A" or str(d.get("type", "")) != "BEGIN_FALL_BACK":
	return "unexpected suggestion: %s %s" % [str(d.get("type", "")), str(d.get("actor_unit_id", ""))]
NetworkIntegration.route_action({"type": "BEGIN_FALL_BACK", "actor_unit_id": "U_PROSECUTORS_A", "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_method("has_pending_stratagem_window") and ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
AIPlayer._execute_ai_movement(1, d)
var u = GameState.state.units.U_PROSECUTORS_A
return bool(u.get("flags", {}).get("fell_back", false)) and not RulesEngine.is_unit_engaged("U_PROSECUTORS_A", GameState.state)
